import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1786900517000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables; there is no config file. The full table lives in the <a href="/reference/environment">environment reference</a> — this page covers the decisions behind them.</p><h2 id="the-url" tabindex="-1">The URL <a class="header-anchor" href="#the-url" aria-label="Permalink to “The URL”">​</a></h2><p><code>WG_EASY_URL</code> is the base URL of the wg-easy web UI, without a trailing path:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>https://vpn.example.com:51821</span></span></code></pre></div><p>Trailing slashes are stripped. The server validates the URL at startup and <strong>exits</strong> — rather than warning — in three cases:</p><table tabindex="0"><thead><tr><th>Rejected</th><th>Why</th></tr></thead><tbody><tr><td>Anything <code>new URL()</code> cannot parse</td><td>A malformed URL turns request paths into guesswork</td></tr><tr><td>A scheme other than <code>http</code>/<code>https</code></td><td>Nothing else can carry the API</td></tr><tr><td>Embedded credentials (<code>user:pass@</code>)</td><td>They would be logged at startup and prefixed onto every request</td></tr></tbody></table><p>Plain <code>http</code> to a non-loopback host only produces a warning, because it is a legitimate setup when the connection already runs inside a tunnel. It is still worth reading that warning: with plain http, both the Basic Auth credentials and every WireGuard private key the server returns travel in the clear.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to “Credentials”">​</a></h2><p><code>WG_EASY_USERNAME</code> and <code>WG_EASY_PASSWORD</code> are the wg-easy <strong>web UI login</strong> of an admin account. Two consequences:</p><ul><li><strong>2FA must be off</strong> for that account. The API speaks Basic Authentication only, and a TOTP-protected account returns <code>HTTP 401</code> on every call.</li><li>The credentials are <strong>deleted from <code>process.env</code></strong> once the config is loaded, so a later crash dump or a child process cannot read them back out.</li></ul><div class="warning custom-block"><p class="custom-block-title">There is no read-only account</p><p>wg-easy admin credentials grant full VPN administration. This server has no way to hand out less than that — see <a href="/guide/security">Security</a>.</p></div><h2 id="self-signed-certificates" tabindex="-1">Self-signed certificates <a class="header-anchor" href="#self-signed-certificates" aria-label="Permalink to “Self-signed certificates”">​</a></h2><p><code>WG_EASY_INSECURE_TLS=true</code> accepts certificates that do not validate. It is implemented as a <strong>scoped undici dispatcher</strong> used only for the wg-easy connection, not <code>NODE_TLS_REJECT_UNAUTHORIZED</code>, so nothing else the process does loses certificate validation.</p><p>It is still the second-best answer. Prefer issuing the wg-easy certificate from an internal CA and trusting that CA on the machine running the server; then leave this unset.</p><h2 id="starting-without-credentials" tabindex="-1">Starting without credentials <a class="header-anchor" href="#starting-without-credentials" aria-label="Permalink to “Starting without credentials”">​</a></h2><p>If any of the three required variables is missing, the server <strong>still starts</strong>. It completes the MCP handshake, lists all eleven tools, and fails every actual call with the same setup instructions it printed on stderr.</p><p>That is deliberate: registries and sandbox inspectors start the server with no environment at all to enumerate its tools. Exiting at startup would leave the listing empty.</p><h2 id="where-the-values-live" tabindex="-1">Where the values live <a class="header-anchor" href="#where-the-values-live" aria-label="Permalink to “Where the values live”">​</a></h2><p>Pass them through your MCP client&#39;s <code>env</code> block, as shown in <a href="/guide/clients">Connecting clients</a>. Avoid putting the password on a command line — it lands in shell history and in <code>ps</code> output — and avoid committing it to a config file that is under version control.</p>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};